      "content": "import { createHash, randomBytes } from 'node:crypto';\nimport { readFileSync, writeFileSync, mkdirSync, realpathSync, watchFile, unwatchFile, openSync, closeSync, fsyncSync, renameSync, unlinkSync, statSync } from 'node:fs';\nimport { dirname, join, isAbsolute } from 'node:path';\nimport { homedir } from 'node:os';\nimport { spawn } from 'node:child_process';\nimport { isDeepStrictEqual } from 'node:util';\n\n/**\n * dsh-mcp-manager — host half.\n *\n * A profile-level MCP server manager for DeepSeek Harness (DSH):\n *   - Settings → MCP page (client half) to add/remove servers\n *   - Two transports per server:\n *       • Streamable HTTP with OAuth (browser redirect, RFC 6749 + PKCE,\n *         RFC 7591 dynamic client registration) or a static Bearer token\n *       • Local stdio process (JSON-RPC over stdin/stdout, newline-delimited),\n *         e.g. `npx`, `uvx`, `python`\n *   - Connects and registers each server's tools into `ctx.tools` as\n *     `mcp__<serverName>__<rawName>` (same convention as the built-in\n *     @deepseek-ai/dsh-mcp-client)\n *   - Persists server configs and OAuth tokens at ~/.dsh/mcp-manager.json;\n *     auto-reconnects and refreshes tokens across restarts. Static bearer\n *     tokens are never stored: only the name of the environment variable that\n *     holds them (`tokenEnv`) is persisted, plus `headers`/`headerEnv` for\n *     Codex-style custom HTTP headers.\n *\n * HTTP surface (mounted on the DSH GUI webserver):\n *   GET  /mcp-manager/api/ping            liveness + version probe\n *   GET  /mcp-manager/api/settings        profile-level feature settings\n *   POST /mcp-manager/api/settings/on-demand  toggle broker-mode MCP tools\n *   GET  /mcp-manager/api/servers         list servers with live status\n *   POST /mcp-manager/api/servers         add a server (http or stdio)\n *   PUT  /mcp-manager/api/servers/:id     edit a server (name/type/transport/auth)\n *   POST /mcp-manager/api/servers/:id/auth     start OAuth (returns authorizeUrl)\n *   POST /mcp-manager/api/servers/:id/connect  (re)connect\n *   POST /mcp-manager/api/servers/:id/enabled  enable/disable globally ({enabled: bool});\n *                                              disabling unregisters all tools and drops\n *                                              the connection, config + tokens persist\n *   DEL  /mcp-manager/api/servers/:id          remove the server\n *   GET  /mcp-manager/callback/:id             OAuth redirect receiver\n *\n * The browser-facing origin (host/port of the GUI webserver) is derived from\n * each request's headers — nothing is hardcoded, so any listen address works.\n */\n\nconst STATE_PATH = join(homedir(), '.dsh', 'mcp-manager.json');\nconst API_PREFIX = '/mcp-manager/api';\nconst CALLBACK_PATH = '/mcp-manager/callback';\n// Per-workspace declarative config, Claude/Codex-style (same shape as the\n// global servers, plus an optional `exclude` list of global server names to\n// mask inside that workspace).\nconst WORKSPACE_CONFIG_REL = join('.dsh', 'dshmm', 'mcp.json');\n/**\n * MCP protocol revision this client asks for during `initialize`. Every transport\n * sends the same value; the server may answer with a revision of its own choosing,\n * which `logNegotiatedProtocol` surfaces instead of silently diverging from it.\n */\nconst MCP_PROTOCOL_VERSION = '2025-03-26';\n\nfunction b64url(buf) {\n  return buf.toString('base64').replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/g, '');\n}\n\n/**\n * Parse an RFC 6750 `WWW-Authenticate: Bearer k=\"v\", ...` challenge into a\n * lower-cased parameter map. Returns null when there is no Bearer challenge.\n * Quoted values may contain commas and escaped quotes; tokens may be bare.\n */\nexport function parseBearerChallenge(header) {\n  if (typeof header !== 'string' || !header) return null;\n  const start = header.search(/(^|[\\s,])Bearer(\\s|$)/i);\n  if (start < 0) return null;\n  const rest = header.slice(start).replace(/^[\\s,]*Bearer/i, '');\n  const params = {};\n  const re = /\\s*,?\\s*([A-Za-z0-9_.-]+)\\s*=\\s*(?:\"((?:[^\"\\\\]|\\\\.)*)\"|([^\\s,]+))/gy;\n  let match;\n  while ((match = re.exec(rest)) !== null) {\n    const key = match[1].toLowerCase();\n    if (!(key in params)) params[key] = match[2] !== undefined ? match[2].replace(/\\\\(.)/g, '$1') : match[3];\n  }\n  return params;\n}\n\n/**\n * Normalize a space-delimited OAuth scope string (RFC 6749 §3.3): collapse\n * whitespace, drop duplicates and characters outside the scope-token grammar.\n * Bounded so a hostile header cannot bloat the state file.\n */\nexport function cleanScope(value) {\n  if (typeof value !== 'string') return '';\n  const out = [];\n  for (const token of value.split(/\\s+/)) {\n    if (!token || !/^[\\x21\\x23-\\x5B\\x5D-\\x7E]+$/.test(token) || out.includes(token)) continue;\n    out.push(token);\n  }\n  const joined = out.join(' ');\n  return joined.length > 512 ? '' : joined;\n}\n\n/** `scopes_supported` (RFC 8414 / RFC 9728) as a clean list of scope tokens. */\nexport function scopeList(value) {\n  if (!Array.isArray(value)) return [];\n  return cleanScope(value.filter((item) => typeof item === 'string').join(' ')).split(' ').filter(Boolean);\n}\n\n/**\n * `token_endpoint_auth_methods_supported` (RFC 8414 §2) as a clean list of\n * method names. Discovery feeds this to the dynamic-registration request, which\n * must ask for a method the authorization server actually advertises.\n */\nexport function authMethodList(value) {\n  if (!Array.isArray(value)) return [];\n  return value.filter((item) => typeof item === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(item));\n}\n\nfunction loadState() {\n  try {\n    return JSON.parse(readFileSync(STATE_PATH, 'utf8'));\n  } catch {\n    return { servers: [] };\n  }\n}\n\nfunction writeStateAtomically(state) {\n  // Atomic replace: a crash between truncate and write must never leave the\n  // token file empty or half-written. The temp file is created 0600 in the\n  // same directory (same filesystem), fsynced, then renamed over the target.\n  const dir = dirname(STATE_PATH);\n  mkdirSync(dir, { recursive: true, mode: 0o700 });\n  const tmp = `${STATE_PATH}.${process.pid}.${randomBytes(12).toString('hex')}.tmp`;\n  let fd;\n  try {\n    fd = openSync(tmp, 'wx', 0o600);\n    writeFileSync(fd, JSON.stringify(state, null, 2));\n    fsyncSync(fd);\n    closeSync(fd);\n    fd = undefined;\n    renameSync(tmp, STATE_PATH);\n    try {\n      const dfd = openSync(dir, 'r');\n      try { fsyncSync(dfd); } finally { closeSync(dfd); }\n    } catch {}\n  } catch (error) {\n    if (fd !== undefined) { try { closeSync(fd); } catch {} }\n    try { unlinkSync(tmp); } catch {}\n    throw error;\n  }\n}\n\n// All writers share the refresh lock. Never steal a lock from a living owner:\n// discovery plus a token request may legitimately exceed the stale threshold.\nconst STATE_LOCK = `${STATE_PATH}.refresh.lock`;\nfunction tryStateLock(lockPath = STATE_LOCK) {\n  mkdirSync(dirname(STATE_PATH), { recursive: true, mode: 0o700 });\n  const owner = `${process.pid}\\n${randomBytes(16).toString('hex')}\\n`;\n  let fd;\n  try {\n    fd = openSync(lockPath, 'wx', 0o600);\n    writeFileSync(fd, owner);\n    closeSync(fd);\n    fd = undefined;\n    return () => {\n      try { if (readFileSync(lockPath, 'utf8') === owner) unlinkSync(lockPath); } catch {}\n    };\n  } catch (error) {\n    if (fd !== undefined) { try { closeSync(fd); } catch {} try { unlinkSync(lockPath); } catch {} }\n    if (error?.code !== 'EEXIST') throw error;\n    return null;\n  }\n}\nasync function acquireStateFileLock(timeoutMs = 25000) {\n  const started = Date.now();\n  for (;;) {\n    const release = tryStateLock();\n    if (release) return release;\n    try {\n      if (Date.now() - statSync(STATE_LOCK).mtimeMs > 120000) {\n        // Only one reclaimer may inspect/unlink a stale owner. Otherwise two\n        // reclaimers could both pass the check and the second remove a new lock.\n        // A crash while holding this short guard fails closed: an operator must\n        // verify/remove the orphaned .reclaim file before stale recovery resumes.\n        const releaseReclaimer = tryStateLock(`${STATE_LOCK}.reclaim`);\n        if (releaseReclaimer) {\n          try {\n            const owner = readFileSync(STATE_LOCK, 'utf8');\n            const pid = Number(owner.split('\\n')[0]);\n            if (Date.now() - statSync(STATE_LOCK).mtimeMs > 120000) {\n              let abandoned = !Number.isSafeInteger(pid) || pid <= 0;\n              if (!abandoned) {\n                try { process.kill(pid, 0); } catch (error) { abandoned = error.code === 'ESRCH'; }\n              }\n              if (abandoned && readFileSync(STATE_LOCK, 'utf8') === owner) unlinkSync(STATE_LOCK);\n            }\n          } finally { releaseReclaimer(); }\n        }\n      }\n    } catch {}\n    if (Date.now() - started >= timeoutMs) throw new Error('state lock timeout; retry the operation');\n    await new Promise(resolve => setTimeout(resolve, 50));\n  }\n}\n\n// Queue ownership, including refreshes, rather than only saveState calls:\n// a refresh persists while holding the lock and must never wait behind a\n// configuration save that is itself waiting for that refresh's lock.\nlet stateLockTail = Promise.resolve();\nlet pendingStateLocks = 0;\nfunction acquireStateLock(timeoutMs = 25000) {\n  const previous = stateLockTail;\n  let advance;\n  stateLockTail = new Promise(resolve => { advance = resolve; });\n  pendingStateLocks += 1;\n  return previous.then(async () => {\n    let releaseFile;\n    try { releaseFile = await acquireStateFileLock(timeoutMs); }\n    catch (error) { pendingStateLocks -= 1; advance(); throw error; }\n    let released = false;\n    return () => {\n      if (released) return;\n      released = true;\n      try { releaseFile(); }\n      finally { pendingStateLocks -= 1; advance(); }\n    };\n  });\n}\n\n// Three-way merge: carry forwa